import sys
from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def dfs(graph, u, p, tin, low, visited, timer, bridges, sizes, component_size):
    visited[u] = True
    tin[u] = low[u] = timer[0]
    timer[0] += 1
    children = 0
    for v in graph[u]:
        if v == p:
            continue
        if visited[v]:
            low[u] = min(low[u], tin[v])
        else:
            dfs(graph, v, u, tin, low, visited, timer, bridges, sizes, component_size)
            low[u] = min(low[u], low[v])
            children += 1
            if low[v] >= tin[u] and p != -1:
                bridges.add((min(u, v), max(u, v)))
    if p == -1 and children > 1:
        bridges.add((min(u, graph[u][0]), max(u, graph[u][0])))
    component_size[u] = 1
    for v in graph[u]:
        if v != p and visited[v]:
            component_size[u] += component_size[v]

def count_critical_links(N, M, P, edges):
    parent = list(range(N + 1))
    rank = [0] * (N + 1)
    graph = defaultdict(list)
    for A, B in edges:
        graph[A].append(B)
        graph[B].append(A)
    tin = [0] * (N + 1)
    low = [0] * (N + 1)
    visited = [False] * (N + 1)
    timer = [0]
    bridges = set()
    component_size = [0] * (N + 1)
    for i in range(1, N + 1):
        if not visited[i]:
            dfs(graph, i, -1, tin, low, visited, timer, bridges, sizes, component_size)

    critical_links_count = 0
    for u, v in bridges:
        if abs(component_size[u] - component_size[v]) < P:
            critical_links_count += 1

    return critical_links_count

input = sys.stdin.read().split()
N = int(input[0])
M = int(input[1])
P = int(input[2])
edges = [(int(input[i * 2 + 3]), int(input[i * 2 + 4])) for i in range(M)]
print(count_critical_links(N, M, P, edges))
